mapper.update:
UPDATE assistant_agent_task
SET task_no = #{taskNo}, update_time = #{updateTime}
WHERE id = #{id} AND task_no = #{oldTaskNo} AND is_deleted = 0

mapper.select:
SELECT 
FROM assistant_agent_task t
WHERE t.user_id = #{userId}
  AND t.collection_task_id = #{collectionTaskId}
  AND t.goal_type = #{goalType}
  AND t.status IN (
    'CREATED', 'PLANNING', 'RUNNING', 'WAITING_CONFIRMATION',
    'WAITING_FIELD_DATA', 'REANALYZING'
  )
  AND t.is_deleted = 0
ORDER BY t.id DESC
LIMIT 1

